function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill("#6aa9f7", 100);  // Soft mauve
  brush.fill("#a0d4f8", 80);  // Pale blue
  brush.fill("#d3f3f8", 120);  // Light sky blue
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);

  // Hills
  brush.fill("#397a64", 90);  // Dark green
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 120);
  brush.vertex(300, 180);
  brush.vertex(100, 160);
  brush.endShape(true);

  // Terrain
  brush.fill("#6e7f73", 80);  // Gray
  brush.beginShape();
  brush.vertex(0, 160);
  brush.vertex(400, 160);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);

  // Clouds
  brush.fill("#c7f2f7", 60);  // Whiteish
  brush.beginShape();
  brush.vertex(50, 150);
  brush.vertex(50, 180);
  brush.vertex(100, 170);
  brush.vertex(90, 130);
  brush.endShape(true);

  // Gradients
  brush.fill("#d9d9d9", 60);  // Off-white
  brush.beginShape();
  brush.vertex(0, 100);
  brush.vertex(400, 100);
  brush.vertex(400, 140);
  brush.vertex(0, 140);
  brush.endShape(true);

  // Sunlight
  brush.fill("#d6a64d", 90);  // Yellow-orange
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(250, 50);
  brush.vertex(275, 70);
  brush.vertex(225, 90);
  brush.endShape(true);
}
