function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  fill("#d6eaf2");
  brush.fill("#d6eaf2", 0.1);
  brush.beginShape();
  vertex(0, 0);
  vertex(width, 0);
  vertex(width, height);
  vertex(0, height);
  brush.endShape(true);

  // Horizon line
  stroke("#8c8e92");
  strokeWeight(3);
  line(0, height * 0.8, width, height * 0.8);

  // Hills
  fill("#a9c2a4");
  brush.fill("#a9c2a4", 0.2);
  brush.beginShape();
  vertex(0, height * 0.85);
  vertex(width, height * 0.85);
  vertex(width, height * 0.85 + 20);
  vertex(0, height * 0.85 + 20);
  brush.endShape(true);

  // Grass below
  fill("#b6c6b1");
  brush.fill("#b6c6b1", 0.3);
  brush.beginShape();
  vertex(0, height * 0.9);
  vertex(width, height * 0.9);
  vertex(width, height * 0.9 + 60);
  vertex(0, height * 0.9 + 60);
  brush.endShape(true);

  // Sun
  fill("#f0d967");
  brush.fill("#f0d967", 0.9);
  brush.beginShape();
  vertex(200, height * 0.8 + 10);
  vertex(200, height * 0.8 + 10);
  vertex(200, height * 0.8);
  vertex(200, height * 0.8);
  brush.endShape(true);

  // Dust
  stroke("#d3d3d3");
  strokeWeight(1);
  for (let x = 0; x < width; x += 5) {
    for (let y = 0; y < height; y += 5) {
      brush.fill("#d3d3d3", 0.8);
      brush.circle(x, y, 2);
    }
  }
}
