  brush.beginShape();
  brush.vertex(0, 200, 100); // left
  brush.vertex(400, 200, 100); // right
  brush.vertex(400, 240, 120); // right, slightly lower
  brush.vertex(0, 240, 120); // left, slightly lower
  brush.endShape(true);

  // Lakes / rivers
  brush.fill("#666");
  brush.stroke("#5a5a5a");
  brush.beginShape();
  brush.vertex(0, 260, 130); // left
  brush.vertex(400, 260, 130); // right
  brush.endShape(true);

  // Sun
  brush.fill("#f5b342", 0.8);
  brush.beginShape();
  brush.vertex(200, 200, 120); // center
  brush.vertex(200, 160, 120); // top
